let uid = 0;

/** Amar Bank logo lockups (from the Figma "Amar Bank …" brand components). lockup: horizontal | vertical | mark | bisnis-horizontal | bisnis-vertical; color: color | white | black (bisnis: color = colored wordmark, default = white wordmark for dark surfaces). */
export function AmarBankLogo({ lockup = 'horizontal', color = 'color', height, style, title = 'Amar Bank' }) {
  const id = React.useMemo(() => 'l' + (++uid), []);
  let key;
  if (lockup === 'bisnis-horizontal' || lockup === 'bisnis-vertical') key = 'amar-bank-' + lockup + (color === 'white' || color === 'default' ? '-default' : '-color-text');
  else if (lockup === 'mark') key = 'amar-bank-without-title-' + (color === 'white' ? 'white' : 'color');
  else key = 'amar-bank-' + lockup + '-' + color;
  const svg = (SVG[key] || SVG['amar-bank-horizontal-color']).split('__ID__').join(id).replace('<svg ', '<svg style="display:block;width:auto;height:100%" ');
  return <span role="img" aria-label={title} style={{ display: 'inline-block', height: height || (lockup.includes('vertical') ? 64 : 30), lineHeight: 0, ...style }} dangerouslySetInnerHTML={{ __html: svg }} />;
}

/* Figma family aliases (source set names) */
export const AmarBankHorizontal = (p) => <AmarBankLogo lockup="horizontal" {...p} />;
export const AmarBankVertical = (p) => <AmarBankLogo lockup="vertical" {...p} />;
export const AmarBankWithoutTitle = (p) => <AmarBankLogo lockup="mark" {...p} />;
export const AmarBankBisnisHorizontal = (p) => <AmarBankLogo lockup="bisnis-horizontal" {...p} />;
export const AmarBankBisnisVertical = (p) => <AmarBankLogo lockup="bisnis-vertical" {...p} />;
export default AmarBankLogo;
